+When('I inspect the render function for innerHTML replacement on the todo list', function () {
+  // Parse the render function body from the source
+  const src = this.appSource;
+  // Find the render function: /** ... */ function render() { ... }
+  // Extract the function body between the first { after 'function render()' and its matching }
+  const renderMatch = src.match(/function\s+render\s*\([^)]*\)\s*\{([\s\S]*?)\n\}/);
+  // A more robust approach: find by keyword
+  const renderIdx = src.indexOf('function render()');
+  assert.ok(renderIdx >= 0, 'render function not found in source');
+  
+  // Extract from the opening brace after render() to the matching close brace
+  const bodyStart = src.indexOf('{', renderIdx);
+  assert.ok(bodyStart >= 0, 'render function body not found');
+  
+  // Walk brace depth to find matching close
+  let depth = 0;
+  let bodyEnd = bodyStart;
+  for (let i = bodyStart; i < src.length; i++) {
+    if (src[i] === '{') depth++;
+    if (src[i] === '}') {
+      depth--;
+      if (depth === 0) { bodyEnd = i; break; }
+    }
+  }
+  
+  const renderBody = src.substring(bodyStart + 1, bodyEnd);
+  
+  // Check if render body uses innerHTML assignment specifically on the todo list
